<?php
function progress_keys(int $time): array {$date=(new DateTimeImmutable('@'.intdiv($time,1000)))->setTimezone(new DateTimeZone('Asia/Tehran'));$back=((int)$date->format('w')+1)%7;return ['day'=>$date->format('Y-m-d'),'week'=>$date->modify('-'.$back.' days')->format('Y-m-d')];}
function progress_slices(int $from,int $to,int $amount): array {$out=[];$used=0;if($to<=$from||$amount<=0)return [];while($from<$to){$date=(new DateTimeImmutable('@'.intdiv($from,1000)))->setTimezone(new DateTimeZone('Asia/Tehran'));$next=min($to,$date->modify('tomorrow')->setTime(0,0)->getTimestamp()*1000);$ms=$next===$to?$amount-$used:(int)floor($amount*($next-$from)/($to-$from));$out[]=[...progress_keys($from),'from'=>$from,'to'=>$next,'ms'=>$ms];$amount-=$ms;$from=$next;}return $out;}
function progress_schema_upgrade(): void {
 $cols=sqlite_mode()?rows('PRAGMA table_info('.table('study_groups').')'):rows('SHOW COLUMNS FROM '.table('study_groups'));$names=array_column($cols,sqlite_mode()?'name':'Field');
 foreach(['is_private','is_personal'] as $column)if(!in_array($column,$names,true))query('ALTER TABLE '.table('study_groups').' ADD COLUMN '.$column.' TINYINT NOT NULL DEFAULT 0');
 $definitions=[
 'credit_heads'=>"visit_id VARCHAR(80) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,group_id VARCHAR(64) NOT NULL,accounted_ms BIGINT NOT NULL DEFAULT 0,subject_name VARCHAR(40) NOT NULL DEFAULT 'ثبت قبلی',companion_id VARCHAR(64) NOT NULL DEFAULT ''",
 'study_credits'=>"id VARCHAR(180) PRIMARY KEY,visit_id VARCHAR(80) NOT NULL,user_id VARCHAR(64) NOT NULL,group_id VARCHAR(64) NOT NULL,companion_id VARCHAR(64) NOT NULL DEFAULT '',subject_name VARCHAR(40) NOT NULL,day_key VARCHAR(10) NOT NULL,week_key VARCHAR(10) NOT NULL,active_ms BIGINT NOT NULL,started_at BIGINT NOT NULL,ended_at BIGINT NOT NULL,legacy TINYINT NOT NULL DEFAULT 0",
 'personal_rooms'=>'user_id VARCHAR(64) PRIMARY KEY,group_id VARCHAR(64) NOT NULL',
 'public_shares'=>'user_id VARCHAR(64) PRIMARY KEY,token CHAR(64) NOT NULL UNIQUE,enabled TINYINT NOT NULL DEFAULT 0,display_name VARCHAR(32) NOT NULL,show_daily TINYINT NOT NULL DEFAULT 1,show_weekly TINYINT NOT NULL DEFAULT 1,show_subjects TINYINT NOT NULL DEFAULT 0,show_sessions TINYINT NOT NULL DEFAULT 0,range_days INT NOT NULL DEFAULT 7,updated_at BIGINT NOT NULL'];
 foreach($definitions as $name=>$definition)query('CREATE TABLE IF NOT EXISTS '.table($name).' ('.$definition.')'.migration_options());
 foreach(['credits_user_period_idx'=>'user_id,day_key,week_key','credits_group_period_idx'=>'group_id,day_key,week_key'] as $name=>$fields){$idx=config()['prefix'].$name;$indexes=sqlite_mode()?rows('PRAGMA index_list('.table('study_credits').')'):rows('SHOW INDEX FROM '.table('study_credits'));if(!in_array($idx,array_column($indexes,sqlite_mode()?'name':'Key_name'),true))query('CREATE INDEX `'.$idx.'` ON '.table('study_credits').'('.$fields.')');}
 begin_write();try{
  $legacy=rows('SELECT h.* FROM '.table('room_history').' h LEFT JOIN '.table('credit_heads').' c ON c.visit_id=h.visit_id WHERE c.visit_id IS NULL');
  foreach($legacy as $h){$from=progress_keys((int)$h['entered_at']);$to=progress_keys((int)$h['last_seen']);if((int)$h['active_ms']>0)query('INSERT INTO '.table('study_credits').' (id,visit_id,user_id,group_id,subject_name,day_key,week_key,active_ms,started_at,ended_at,legacy) VALUES (?,?,?,?,?,?,?,?,?,?,1)',['legacy:'.$h['visit_id'],$h['visit_id'],$h['user_id'],$h['group_id'],'ثبت قبلی',$from['day']===$to['day']?$from['day']:'',$from['week']===$to['week']?$from['week']:'',(int)$h['active_ms'],(int)$h['entered_at'],(int)$h['last_seen']]);query('INSERT INTO '.table('credit_heads').' (visit_id,user_id,group_id,accounted_ms) VALUES (?,?,?,?)',[$h['visit_id'],$h['user_id'],$h['group_id'],(int)$h['active_ms']]);}
  query('INSERT INTO '.table('credit_heads').' (visit_id,user_id,group_id,accounted_ms) SELECT r.visit_id,r.user_id,r.group_id,0 FROM '.table('room_presence').' r WHERE NOT EXISTS(SELECT 1 FROM '.table('credit_heads').' c WHERE c.visit_id=r.visit_id)');db()->commit();
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function progress_enter(string $visit,string $user,string $group): void {query('INSERT INTO '.table('credit_heads').' (visit_id,user_id,group_id,accounted_ms) VALUES (?,?,?,0) ON DUPLICATE KEY UPDATE visit_id=VALUES(visit_id)',[$visit,$user,$group]);}
function progress_settle(?string $uid=null): void {
 $own=!db()->inTransaction();if($own)begin_write();try{
  $pending=rows('SELECT h.*,c.accounted_ms,c.subject_name,c.companion_id FROM '.table('room_history').' h JOIN '.table('credit_heads').' c ON c.visit_id=h.visit_id WHERE h.active_ms>c.accounted_ms'.($uid?' AND h.user_id=?':'').' LIMIT 100 FOR UPDATE',$uid?[$uid]:[]);
  foreach($pending as $row){$delta=(int)$row['active_ms']-(int)$row['accounted_ms'];$end=(int)$row['last_seen'];$start=max((int)$row['entered_at'],$end-$delta);
   foreach(progress_slices($start,$end,$delta) as $slice){$id=$row['visit_id'].':'.$slice['day'].':'.hash('sha256',$row['subject_name'].'|'.$row['companion_id']);query('INSERT INTO '.table('study_credits').' (id,visit_id,user_id,group_id,companion_id,subject_name,day_key,week_key,active_ms,started_at,ended_at) VALUES (?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE active_ms='.table('study_credits').'.active_ms+VALUES(active_ms),started_at=LEAST('.table('study_credits').'.started_at,VALUES(started_at)),ended_at=GREATEST('.table('study_credits').'.ended_at,VALUES(ended_at))',[$id,$row['visit_id'],$row['user_id'],$row['group_id'],$row['companion_id'],$row['subject_name'],$slice['day'],$slice['week'],$slice['ms'],$slice['from'],$slice['to']]);}
   query('UPDATE '.table('credit_heads').' SET accounted_ms=? WHERE visit_id=?',[(int)$row['active_ms'],$row['visit_id']]);
  }if($own)db()->commit();
 }catch(Throwable $e){if($own&&db()->inTransaction())db()->rollBack();throw $e;}
}
function progress_totals(string $uid,?string $group=null): array {$keys=progress_keys(now_ms());$scope=$group?' AND (group_id=? OR companion_id=?)':'';$params=[$keys['day'],$keys['week'],$uid,...($group?[$group,$group]:[])];$totals=one('SELECT COALESCE(SUM(CASE WHEN day_key=? THEN active_ms ELSE 0 END),0) AS dailyMs,COALESCE(SUM(CASE WHEN week_key=? THEN active_ms ELSE 0 END),0) AS weeklyMs,COALESCE(SUM(active_ms),0) AS totalMs FROM '.table('study_credits').' WHERE user_id=?'.$scope,$params);return ['period'=>$keys,'dailyMs'=>(int)$totals['dailyMs'],'weeklyMs'=>(int)$totals['weeklyMs'],'totalMs'=>(int)$totals['totalMs']];}
function progress_rank(string $uid): array {$keys=progress_keys(now_ms());$list=rows('SELECT c.user_id AS userId,u.display_name AS name,SUM(CASE WHEN c.day_key=? THEN c.active_ms ELSE 0 END) AS dailyMs,SUM(CASE WHEN c.week_key=? THEN c.active_ms ELSE 0 END) AS weeklyMs,COALESCE(SUM(active_ms),0) AS totalMs FROM '.table('study_credits').' c JOIN '.table('users').' u ON u.id=c.user_id JOIN '.table('study_groups').' g ON g.id=c.group_id JOIN '.table('group_members')." me ON me.group_id=g.id AND me.user_id=? AND me.status='approved' JOIN ".table('group_members')." m ON m.group_id=g.id AND m.user_id=c.user_id AND m.status='approved' WHERE g.deleted_at=0 AND g.archived=0 AND g.is_private=0 AND u.disabled=0 GROUP BY c.user_id,u.display_name",[$keys['day'],$keys['week'],$uid]);$rank=[];foreach(['daily'=>'dailyMs','weekly'=>'weeklyMs'] as $label=>$field){$items=[];foreach($list as $item)if((int)$item[$field]>0){$item['dailyMs']=(int)$item['dailyMs'];$item['weeklyMs']=(int)$item['weeklyMs'];$item['activeMs']=$item[$field];$items[]=$item;}usort($items,fn($a,$b)=>$b[$field]<=>$a[$field]?:strcmp($a['name'],$b['name']));$rank[$label]=$items;}return [...$rank,'period'=>[...$keys,'timeZone'=>'Asia/Tehran','weekStartsOn'=>'Saturday']];}
function progress_detach(string $group,?string $user=null): void {query('UPDATE '.table('credit_heads')." SET companion_id='' WHERE companion_id=?".($user?' AND user_id=?':''),[$group,...($user?[$user]:[])]);}
function public_share_settings(?array $row): array {return $row?['enabled'=>(bool)$row['enabled'],'token'=>$row['token'],'name'=>$row['display_name'],'showDaily'=>(bool)$row['show_daily'],'showWeekly'=>(bool)$row['show_weekly'],'showSubjects'=>(bool)$row['show_subjects'],'showSessions'=>(bool)$row['show_sessions'],'rangeDays'=>(int)$row['range_days']]:['enabled'=>false,'token'=>null,'name'=>'','showDaily'=>true,'showWeekly'=>true,'showSubjects'=>false,'showSessions'=>false,'rangeDays'=>7];}
function public_share_save(array $data,string $uid): array {
 foreach(['enabled','showDaily','showWeekly','showSubjects','showSessions'] as $key)if(!is_bool($data[$key]??null))fail(422,'SHARE_OPTIONS','گزینه‌های اشتراک معتبر نیست.');if(!in_array($data['rangeDays']??null,[7,30,90],true)||$data['enabled']&&!($data['showDaily']||$data['showWeekly']||$data['showSubjects']||$data['showSessions']))fail(422,'SHARE_OPTIONS','حداقل یک بخش و بازهٔ معتبر انتخاب کن.');$name=clean_name($data['name']??null);$old=one('SELECT * FROM '.table('public_shares').' WHERE user_id=?',[$uid]);$token=!$old||($data['rotate']??false)===true?bin2hex(random_bytes(32)):$old['token'];
 query('INSERT INTO '.table('public_shares').' (user_id,token,enabled,display_name,show_daily,show_weekly,show_subjects,show_sessions,range_days,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE token=VALUES(token),enabled=VALUES(enabled),display_name=VALUES(display_name),show_daily=VALUES(show_daily),show_weekly=VALUES(show_weekly),show_subjects=VALUES(show_subjects),show_sessions=VALUES(show_sessions),range_days=VALUES(range_days),updated_at=VALUES(updated_at)',[$uid,$token,$data['enabled']?1:0,$name,$data['showDaily']?1:0,$data['showWeekly']?1:0,$data['showSubjects']?1:0,$data['showSessions']?1:0,$data['rangeDays'],now_ms()]);return public_share_settings(one('SELECT * FROM '.table('public_shares').' WHERE user_id=?',[$uid]));
}
function public_share_report(string $token): array {
 if(!preg_match('/^[a-f0-9]{64}$/D',$token))fail(404,'NOT_FOUND','این گزارش در دسترس نیست.');$row=one('SELECT s.* FROM '.table('public_shares').' s JOIN '.table('users').' u ON u.id=s.user_id WHERE s.token=? AND s.enabled=1 AND u.disabled=0',[$token]);if(!$row)fail(404,'NOT_FOUND','این گزارش در دسترس نیست.');room_settle($row['user_id']);$cutoff=progress_keys(now_ms()-((int)$row['range_days']-1)*86400000)['day'];$report=['name'=>$row['display_name'],'rangeDays'=>(int)$row['range_days'],'timeZone'=>'Asia/Tehran','generatedAt'=>now_ms()];
 foreach(['show_daily'=>['daily','day_key','day'],'show_weekly'=>['weekly','week_key','week'],'show_subjects'=>['subjects','subject_name','name']] as $flag=>$fields)if($row[$flag]){$items=rows('SELECT '.$fields[1].' AS '.$fields[2].',SUM(active_ms) AS activeMs FROM '.table('study_credits').' WHERE user_id=? AND day_key>=? GROUP BY '.$fields[1].' ORDER BY '.$fields[1],[$row['user_id'],$cutoff]);foreach($items as &$item)$item['activeMs']=(int)$item['activeMs'];unset($item);$report[$fields[0]]=$items;}
 if($row['show_sessions']){$items=rows('SELECT MIN(started_at) AS start,MAX(ended_at) AS end,SUM(active_ms) AS activeMs FROM '.table('study_credits').' WHERE user_id=? AND day_key>=? GROUP BY visit_id ORDER BY start DESC LIMIT 100',[$row['user_id'],$cutoff]);foreach($items as &$item)foreach(['start','end','activeMs'] as $field)$item[$field]=(int)$item[$field];unset($item);$report['sessions']=$items;}return $report;
}
